(function() {
    'use strict';

    class PortfolioAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'El Portafolio Corporativo';
            this.version = '1.1.0';
            this.ROUNDS = [
                {
                    titleKey: 'round1_title',
                    titleDefault: 'Portfolio Analysis (BCG Matrix)',
                    briefingKey: 'round1_briefing',
                    controls: 'round1Controls'
                },
                {
                    titleKey: 'round2_title',
                    titleDefault: 'Divestiture Alternatives',
                    briefingKey: 'round2_briefing',
                    controls: 'round2Controls'
                },
                {
                    titleKey: 'round3_title',
                    titleDefault: 'Activist Defense Strategy',
                    briefingKey: 'round3_briefing',
                    controls: 'round3Controls'
                },
                {
                    titleKey: 'round4_title',
                    titleDefault: 'Restructuring Plan',
                    briefingKey: 'round4_briefing',
                    controls: 'round4Controls'
                }
            ];
            this.BCG_CORRECT = {
                cement: 'cow',
                construction: 'dog',
                realestate: 'qmark',
                distribution: 'cow',
                textiles: 'dog',
                services: 'qmark'
            };
            this.BCG_LABELS = { star: '★ Star', cow: '🐄 Cash Cow', qmark: '❓ Question Mark', dog: '🐕 Dog' };
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    marketCap: 393,
                    roic: 9.3,
                    ebitda: 90.7,
                    revenue: 534,
                    capitalAvailable: 0,
                    analystConfidence: 35,
                    unitsSold: [],
                    bcgScore: 0,
                    strategyChosen: 0,
                    defenseChosen: 0,
                    totalDivestitureProceeds: 0,
                    marketCapHistory: [393],
                    roicHistory: [9.3],
                    projectedROIC: 9.3,
                    projectedMarketCap: 393
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    strategy: 2,
                    bcgCement: 'cow',
                    bcgConstruction: 'dog',
                    bcgRealEstate: 'qmark',
                    bcgDistribution: 'cow',
                    bcgTextiles: 'dog',
                    bcgServices: 'qmark',
                    sellConstruction: false,
                    sellTextiles: true,
                    sellRealEstate: false,
                    capitalUse: 2,
                    defenseStrategy: 3,
                    allocDividend: 30,
                    allocCement: 40,
                    allocOperations: 20,
                    allocDebt: 10,
                    roicTarget: 10.5
                };
            }
            this._updateBriefing(state);
            this._setupDynamicListeners();
        }

        _setupDynamicListeners() {
            var defenseSelect = document.getElementById('defenseSelect');
            if (defenseSelect) {
                defenseSelect.addEventListener('change', function() {
                    var detail = document.getElementById('defenseDetail');
                    if (!detail) return;
                    var val = parseInt(defenseSelect.value);
                    if (val === 1) {
                        detail.innerHTML = window.mySimulation.t('defense_embrace_detail');
                    } else if (val === 2) {
                        detail.innerHTML = window.mySimulation.t('defense_defend_detail');
                    } else {
                        detail.innerHTML = window.mySimulation.t('defense_negotiate_detail');
                    }
                });
            }
            var allocInputs = ['allocDividend', 'allocCement', 'allocOperations', 'allocDebt'];
            allocInputs.forEach(function(id) {
                var el = document.getElementById(id);
                if (el) {
                    el.addEventListener('input', function() {
                        var total = 0;
                        allocInputs.forEach(function(aid) {
                            var ael = document.getElementById(aid);
                            if (ael) total += parseInt(ael.value) || 0;
                        });
                        var totalEl = document.getElementById('allocTotal');
                        if (totalEl) totalEl.textContent = total;
                    });
                }
            });
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.textContent = window.mySimulation ? window.mySimulation.t(round.titleKey) : round.titleDefault;
            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = window.mySimulation ? window.mySimulation.t(round.briefingKey) : '';
            for (var i = 0; i < this.ROUNDS.length; i++) {
                var panel = document.getElementById(this.ROUNDS[i].controls);
                if (panel) panel.style.display = (i === idx) ? 'block' : 'none';
            }
            if (state.domainState && state.domainState.unitsSold) {
                var sold = state.domainState.unitsSold;
                var statusMap = { construction: 'statusConstruction', textiles: 'statusTextiles', realestate: 'statusRealEstate' };
                Object.keys(statusMap).forEach(function(key) {
                    var el = document.getElementById(statusMap[key]);
                    if (el) {
                        if (sold.indexOf(key) >= 0) {
                            el.textContent = window.mySimulation ? window.mySimulation.t('status_sold') : 'SOLD';
                            el.style.color = '#c0392b';
                            el.style.fontWeight = '700';
                        }
                    }
                });
            }
            if (idx >= 1 && state.domainState) {
                var bcgMap = { bcgCement: state.decisions ? state.decisions.bcgCement : '', bcgConstruction: state.decisions ? state.decisions.bcgConstruction : '', bcgRealEstate: state.decisions ? state.decisions.bcgRealEstate : '', bcgDistribution: state.decisions ? state.decisions.bcgDistribution : '', bcgTextiles: state.decisions ? state.decisions.bcgTextiles : '', bcgServices: state.decisions ? state.decisions.bcgServices : '' };
                var self = this;
                Object.keys(bcgMap).forEach(function(elId) {
                    var el = document.getElementById(elId);
                    if (el && bcgMap[elId]) el.textContent = self.BCG_LABELS[bcgMap[elId]] || bcgMap[elId];
                });
            }
            var bar = document.getElementById('analystBar');
            if (bar && state.domainState) bar.style.width = state.domainState.analystConfidence + '%';
        }

        validateDecisions(decisions) {
            var period = window.mySimulation.state.currentPeriod || 1;
            if (period === 1) {
                var stratEl = document.getElementById('strategySelect');
                if (stratEl) decisions.strategy = parseInt(stratEl.value);
                decisions.bcgCement = document.getElementById('bcgCementSelect') ? document.getElementById('bcgCementSelect').value : 'cow';
                decisions.bcgConstruction = document.getElementById('bcgConstructionSelect') ? document.getElementById('bcgConstructionSelect').value : 'dog';
                decisions.bcgRealEstate = document.getElementById('bcgRealEstateSelect') ? document.getElementById('bcgRealEstateSelect').value : 'qmark';
                decisions.bcgDistribution = document.getElementById('bcgDistributionSelect') ? document.getElementById('bcgDistributionSelect').value : 'cow';
                decisions.bcgTextiles = document.getElementById('bcgTextilesSelect') ? document.getElementById('bcgTextilesSelect').value : 'dog';
                decisions.bcgServices = document.getElementById('bcgServicesSelect') ? document.getElementById('bcgServicesSelect').value : 'qmark';
            } else if (period === 2) {
                decisions.sellConstruction = document.getElementById('sellConstruction') ? document.getElementById('sellConstruction').checked : false;
                decisions.sellTextiles = document.getElementById('sellTextiles') ? document.getElementById('sellTextiles').checked : false;
                decisions.sellRealEstate = document.getElementById('sellRealEstate') ? document.getElementById('sellRealEstate').checked : false;
                var capEl = document.getElementById('capitalUseSelect');
                if (capEl) decisions.capitalUse = parseInt(capEl.value);
                if (!decisions.sellConstruction && !decisions.sellTextiles && !decisions.sellRealEstate) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_no_divest'), 'warning');
                    return false;
                }
            } else if (period === 3) {
                var defEl = document.getElementById('defenseSelect');
                if (defEl) decisions.defenseStrategy = parseInt(defEl.value);
            } else if (period === 4) {
                decisions.allocDividend = parseInt(document.getElementById('allocDividend') ? document.getElementById('allocDividend').value : 30);
                decisions.allocCement = parseInt(document.getElementById('allocCement') ? document.getElementById('allocCement').value : 40);
                decisions.allocOperations = parseInt(document.getElementById('allocOperations') ? document.getElementById('allocOperations').value : 20);
                decisions.allocDebt = parseInt(document.getElementById('allocDebt') ? document.getElementById('allocDebt').value : 10);
                decisions.roicTarget = parseFloat(document.getElementById('roicTarget') ? document.getElementById('roicTarget').value : 10.5);
                var allocSum = decisions.allocDividend + decisions.allocCement + decisions.allocOperations + decisions.allocDebt;
                if (allocSum !== 100) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_alloc_100'), 'warning');
                    return false;
                }
                if (decisions.roicTarget < 8 || decisions.roicTarget > 16) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_roic_range'), 'warning');
                    return false;
                }
            }
            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var marketCapChange = 0;
            var roicChange = 0;
            var confidenceChange = 0;
            var roundLabel = '';
            var roundDetail = '';

            if (period === 1) {
                var bcgScore = 0;
                var bcgChecks = { cement: d.bcgCement, construction: d.bcgConstruction, realestate: d.bcgRealEstate, distribution: d.bcgDistribution, textiles: d.bcgTextiles, services: d.bcgServices };
                var self = this;
                Object.keys(bcgChecks).forEach(function(key) {
                    if (bcgChecks[key] === self.BCG_CORRECT[key]) bcgScore += 1;
                });
                ds.bcgScore = bcgScore;
                var strategyBonus = 0;
                if (d.strategy === 1) { strategyBonus = -5; confidenceChange = -8; roundDetail = 'Maintain all — market skeptical'; }
                else if (d.strategy === 2) { strategyBonus = 12; confidenceChange = 15; roundDetail = 'Divest Dogs — market optimistic'; }
                else if (d.strategy === 3) { strategyBonus = 8; confidenceChange = 10; roundDetail = 'Spinoff Cement — market cautiously positive'; }
                ds.strategyChosen = d.strategy;
                var bcgBonus = (bcgScore - 3) * 3;
                marketCapChange = strategyBonus + bcgBonus;
                confidenceChange += bcgScore * 3;
                roundLabel = 'Portfolio Strategy';
            } else if (period === 2) {
                var proceeds = 0;
                var revLost = 0;
                var ebitdaLost = 0;
                var roicImprovement = 0;
                if (d.sellConstruction) {
                    proceeds += 40; revLost += 89; ebitdaLost += 7.2;
                    ds.unitsSold.push('construction');
                    roicImprovement += 0.4;
                }
                if (d.sellTextiles) {
                    proceeds += 35; revLost += 78; ebitdaLost += 4.9;
                    ds.unitsSold.push('textiles');
                    roicImprovement += 0.5;
                }
                if (d.sellRealEstate) {
                    proceeds += 17; revLost += 34; ebitdaLost += 2.1;
                    ds.unitsSold.push('realestate');
                    roicImprovement += 0.2;
                }
                ds.totalDivestitureProceeds = proceeds;
                ds.capitalAvailable = proceeds;
                ds.revenue -= revLost;
                ds.ebitda -= ebitdaLost;
                ds.roic += roicImprovement;
                roicChange = roicImprovement;
                var capitalUseBonus = 0;
                if (d.capitalUse === 1) { capitalUseBonus = 5; confidenceChange = 8; }
                else if (d.capitalUse === 2) { capitalUseBonus = 15; confidenceChange = 12; }
                else if (d.capitalUse === 3) { capitalUseBonus = 10; confidenceChange = 10; }
                else if (d.capitalUse === 4) { capitalUseBonus = 8; confidenceChange = 6; }
                else if (d.capitalUse === 5) { capitalUseBonus = 4; confidenceChange = 4; }
                marketCapChange = capitalUseBonus + Math.round(proceeds * 0.3);
                roundLabel = 'Divestiture';
                roundDetail = 'Sold ' + ds.unitsSold.length + ' units for $' + proceeds + 'M';
            } else if (period === 3) {
                ds.defenseChosen = d.defenseStrategy;
                if (d.defenseStrategy === 1) {
                    marketCapChange = 20;
                    confidenceChange = 25;
                    roicChange = 0.3;
                    roundDetail = 'Embraced activist — strong market reaction';
                } else if (d.defenseStrategy === 2) {
                    marketCapChange = -25;
                    confidenceChange = -20;
                    roicChange = 0;
                    roundDetail = 'Defended status quo — market punished stock';
                } else {
                    marketCapChange = 15;
                    confidenceChange = 18;
                    roicChange = 0.2;
                    roundDetail = 'Negotiated compromise — balanced market response';
                }
                ds.roic += roicChange;
                roundLabel = 'Activist Defense';
            } else if (period === 4) {
                var cementBoost = d.allocCement * 0.08;
                var opsBoost = d.allocOperations * 0.05;
                var debtBoost = d.allocDebt * 0.03;
                var dividendPenalty = d.allocDividend > 50 ? (d.allocDividend - 50) * -0.04 : 0;
                roicChange = Math.round((cementBoost + opsBoost + debtBoost + dividendPenalty) * 10) / 100;
                ds.roic += roicChange;
                ds.projectedROIC = d.roicTarget;
                var targetAmbition = d.roicTarget - ds.roic;
                if (targetAmbition > 0 && targetAmbition < 1.5) { confidenceChange = 12; marketCapChange = 20; }
                else if (targetAmbition >= 1.5 && targetAmbition < 3) { confidenceChange = 8; marketCapChange = 15; }
                else if (targetAmbition >= 3) { confidenceChange = -5; marketCapChange = -10; }
                else { confidenceChange = 5; marketCapChange = 10; }
                if (d.allocCement >= 30) { marketCapChange += 10; confidenceChange += 5; }
                if (d.allocOperations >= 20) { marketCapChange += 5; }
                ds.capitalAvailable = 0;
                ds.projectedMarketCap = ds.marketCap + marketCapChange;
                roundLabel = 'Restructuring Plan';
                roundDetail = 'ROIC target: ' + d.roicTarget + '% | Capital deployed';
            }

            ds.marketCap += marketCapChange;
            ds.analystConfidence = Math.max(0, Math.min(100, ds.analystConfidence + confidenceChange));
            ds.marketCapHistory.push(ds.marketCap);
            ds.roicHistory.push(Math.round(ds.roic * 10) / 10);

            var ebitdaMargin = ds.revenue > 0 ? Math.round((ds.ebitda / ds.revenue) * 1000) / 10 : 0;

            // v1.1.0 FIX: persist a 0-100 score where the grading/reporting layer reads
            // it (domainState.performance.overallScore, then domainState.score). Score
            // was previously computed only in getPerformanceSummary and never persisted.
            var _sc = this._computeScore(ds);
            ds.performance = { overallScore: _sc.total, grade: _sc.performance };
            ds.score = _sc.total;

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1, domainState: ds, decisions: d });
            }, 500);

            return {
                period: period,
                roundLabel: roundLabel,
                roundDetail: roundDetail,
                marketCap: ds.marketCap,
                marketCapChange: marketCapChange,
                roic: Math.round(ds.roic * 10) / 10,
                roicChange: Math.round(roicChange * 10) / 10,
                ebitda: Math.round(ds.ebitda * 10) / 10,
                ebitdaMargin: ebitdaMargin,
                revenue: Math.round(ds.revenue),
                analystConfidence: ds.analystConfidence,
                capitalAvailable: ds.capitalAvailable,
                overallScore: _sc.total
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('marketCapDisplay', 'domainState.marketCap', function(v) { return '$' + Math.round(v) + 'M'; });
            uiManager.bind('roicDisplay', 'domainState.roic', function(v) { return (Math.round(v * 10) / 10) + '%'; });
            uiManager.bind('ebitdaDisplay', 'domainState.ebitda', function(v) { return '$' + (Math.round(v * 10) / 10) + 'M'; });
            uiManager.bind('revenueDisplay', 'domainState.revenue', function(v) { return '$' + Math.round(v) + 'M'; });
            uiManager.bind('capitalDisplay', 'domainState.capitalAvailable', function(v) { return '$' + Math.round(v) + 'M'; });
            uiManager.bind('analystDisplay', 'domainState.analystConfidence', function(v) { return Math.round(v) + '%'; });
        }

        getChartConfig() {
            return {
                valuationChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Market Cap ($M)',
                            data: [],
                            borderColor: '#1a2744',
                            backgroundColor: 'rgba(26,39,68,0.08)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.2,
                            pointBackgroundColor: '#c9a84c',
                            pointBorderColor: '#1a2744',
                            pointRadius: 5
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: 'Market Capitalization', color: '#1a2744', font: { size: 13, weight: '700' } } },
                        scales: { y: { beginAtZero: false, grid: { color: 'rgba(26,39,68,0.06)' } }, x: { grid: { display: false } } }
                    }
                },
                roicChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Group ROIC (%)',
                            data: [],
                            backgroundColor: 'rgba(201,168,76,0.7)',
                            borderColor: '#c9a84c',
                            borderWidth: 2,
                            borderRadius: 3
                        }, {
                            label: 'Cost of Capital (10%)',
                            data: [],
                            type: 'line',
                            borderColor: '#c0392b',
                            borderWidth: 2,
                            borderDash: [6, 3],
                            pointRadius: 0,
                            fill: false
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: 'ROIC vs Cost of Capital', color: '#1a2744', font: { size: 13, weight: '700' } } },
                        scales: { y: { beginAtZero: false, min: 7, max: 14, grid: { color: 'rgba(26,39,68,0.06)' } }, x: { grid: { display: false } } }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.marketCapHistory.map(function(_, i) { return i === 0 ? 'Start' : 'R' + i; });
            var cocLine = state.domainState.roicHistory.map(function() { return 10; });
            return {
                valuationChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.marketCapHistory }]
                },
                roicChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.roicHistory },
                        { data: cocLine }
                    ]
                }
            };
        }

        // v1.1.0: single source of truth for the 0-100 score, shared by
        // calculateResults() (persisted into domainState) and getPerformanceSummary()
        // (completion modal). Formula/thresholds UNCHANGED; reads marketCap, roic,
        // analystConfidence and bcgScore from domainState.
        _computeScore(ds) {
            ds = ds || {};
            var finalMarketCap = (ds.marketCap != null) ? ds.marketCap : 393;
            var finalROIC = (ds.roic != null) ? ds.roic : 9.3;
            var finalConfidence = (ds.analystConfidence != null) ? ds.analystConfidence : 35;
            var marketCapGain = finalMarketCap - 393;
            var roicGain = Math.round((finalROIC - 9.3) * 10) / 10;
            var score = 0;
            score += Math.min(30, Math.max(0, marketCapGain));
            score += Math.min(30, Math.max(0, roicGain * 15));
            score += Math.min(20, Math.max(0, finalConfidence * 0.2));
            score += (ds.bcgScore || 0) * 3;
            score = Math.round(Math.min(100, Math.max(0, score)));
            var performance = 'Needs Improvement';
            if (score >= 75) performance = 'Excellent';
            else if (score >= 55) performance = 'Good';
            else if (score >= 35) performance = 'Adequate';
            return { total: score, performance: performance };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var lastRound = history[history.length - 1];
            var lds = lastRound.domainState || {};
            var finalMarketCap = lastRound.results ? lastRound.results.marketCap : (lds.marketCap != null ? lds.marketCap : 393);
            var finalROIC = lastRound.results ? lastRound.results.roic : (lds.roic != null ? lds.roic : 9.3);
            var finalConfidence = lastRound.results ? lastRound.results.analystConfidence : (lds.analystConfidence != null ? lds.analystConfidence : 35);
            var marketCapGain = finalMarketCap - 393;
            var roicGain = Math.round((finalROIC - 9.3) * 10) / 10;
            // v1.1.0 FIX: the BCG-matrix component was always 0 because the old code read
            // history[0].results.bcgScore, but the results object never carried bcgScore.
            // domainState does, so scoring via _computeScore(domainState) makes the BCG
            // analysis (a core learning objective, up to 18 pts) correctly count.
            var _sc = this._computeScore(lds);
            var score = _sc.total;
            var performance = _sc.performance;
            var insights = [];
            if (finalROIC > 10) insights.push('Successfully brought ROIC above cost of capital — value creation achieved.');
            else insights.push('ROIC remains below cost of capital — the conglomerate is still destroying value.');
            if (finalMarketCap > 450) insights.push('Market capitalization recovered strongly from the activist crisis.');
            else if (finalMarketCap > 393) insights.push('Modest recovery in market capitalization.');
            else insights.push('Market capitalization declined further — restructuring plan was not convincing.');
            if (finalConfidence > 65) insights.push('Analyst confidence is high — the market believes in the plan.');
            return {
                score: score,
                finalMarketCap: finalMarketCap,
                finalROIC: finalROIC,
                marketCapGain: marketCapGain,
                roicGain: roicGain,
                analystConfidence: finalConfidence,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var period = results.period;
            if (period === 1 && results.roic < 10) return window.mySimulation.t('hint_roic_below');
            if (period === 2 && results.capitalAvailable > 60) return window.mySimulation.t('hint_large_proceeds');
            if (period === 3 && results.analystConfidence < 30) return window.mySimulation.t('hint_low_confidence');
            if (period === 3 && results.analystConfidence > 60) return window.mySimulation.t('hint_high_confidence');
            if (period === 4 && results.roic < 10) return window.mySimulation.t('hint_final_roic_low');
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.roundLabel', label: 'Round', i18nKey: 'col_round' },
                { key: 'results.marketCap', label: 'Market Cap', i18nKey: 'col_mktcap', formatter: function(v) { return '$' + v + 'M'; } },
                { key: 'results.marketCapChange', label: 'Change', i18nKey: 'col_change', formatter: function(v) { return (v >= 0 ? '+' : '') + v + 'M'; } },
                { key: 'results.roic', label: 'ROIC', i18nKey: 'col_roic', formatter: function(v) { return v + '%'; } },
                { key: 'results.analystConfidence', label: 'Confidence', i18nKey: 'col_confidence', formatter: function(v) { return v + '%'; } },
                { key: 'results.roundDetail', label: 'Detail', i18nKey: 'col_detail' }
            ];
        }

        getPresets() { return null; }

        getTranslations() {
            return {
                en: {
                    title: `The Corporate Portfolio`,
                    subtitle: `Grupo Industrial Atlántico S.A. — San Pedro Sula, Honduras`,
                    round_label: `Round`,
                    period_of: `of`,
                    round1_title: `Portfolio Analysis (BCG Matrix)`,
                    round2_title: `Divestiture Alternatives`,
                    round3_title: `Activist Defense Strategy`,
                    round4_title: `Restructuring Plan`,
                    kpi_market_cap: `Market Cap`,
                    kpi_roic: `Group ROIC`,
                    kpi_ebitda: `EBITDA`,
                    kpi_revenue: `Revenue`,
                    kpi_capital_avail: `Capital Available`,
                    kpi_analyst: `Analyst Confidence`,
                    briefing_label: `Situation Briefing`,
                    bu_table_heading: `Business Unit Portfolio`,
                    col_bu: `Business Unit`,
                    col_rev: `Revenue`,
                    col_ebitda_pct: `EBITDA %`,
                    col_roic: `ROIC`,
                    col_bcg: `BCG Class`,
                    col_status: `Status`,
                    status_active: `Active`,
                    status_sold: `SOLD`,
                    decisions_heading: `Your Decisions`,
                    r1_strategy_label: `Portfolio Strategy`,
                    r1_opt_maintain: `Maintain diversified portfolio — keep all units`,
                    r1_opt_divest: `Divest Dogs — sell low-ROIC units, focus on Cash Cows and Question Marks`,
                    r1_opt_spinoff: `Spin off Cement as independent public company`,
                    r2_divest_label: `Select units to divest`,
                    r2_sell_construction: `Sell Construcción Atlántica (~$40M)`,
                    r2_sell_textiles: `Sell Textiles Atlántico (~$35M)`,
                    r2_sell_realestate: `Sell Atlántico Propiedades (~$17M)`,
